class Solution:

	def maxSquare(self, n, m, mat):
		mx = 0
		dp = [[0 for j in range(m + 1)] for i in range(n + 1)]
		for i in range(n - 1, -1, -1):
			for j in range(m - 1, -1, -1):
				right = dp[i][j + 1]
				diag = dp[i + 1][j + 1]
				down = dp[i + 1][j]
				if mat[i][j] == 1:
					dp[i][j] = 1 + min(right, min(diag, down))
					mx = max(mx, dp[i][j])
				else:
					dp[i][j] = 0
		return mx
